// GradientBackground — "HANZO Camera Lens", made with the 21st.dev Gradient
// Builder and exported as live CSS (the builder's own Copy-CSS background,
// plus its soften-blur and grain passes). Zero dependencies: one <div> that
// fills its parent. Drop it behind your content:
// <div className="relative h-96"><GradientBackground className="absolute inset-0" /></div>
// Remix the source recipe (colors, mode, finish) in the editor:
// https://21st.dev/community/gradients/editor?from=cc4cdb76-4f67-480e-a01d-ee545a0504aa
export function GradientBackground({ className }: { className?: string }) {
  return (
    <div
      aria-hidden="true"
      className={className}
      style={{
        position: "relative",
        overflow: "hidden",
        width: "100%",
        height: "100%",
        containerType: "size",
      }}
    >
      <div
        style={{
          position: "absolute",
        inset: 0,
        backgroundColor: "#0A0A0A",
        backgroundImage:
          "radial-gradient(circle at 50% 50%, #0a0a0a 0%, #0a0a0a 14.5%, #881c1c 18.83%, #881c1c 31.17%, #ca2626 35.5%, #ca2626 47.83%, #931f1f 52.17%, #931f1f 64.5%, #5d2121 68.83%, #5d2121 81.17%, #262626 85.5%, #262626 100%)",
        }}
      />
    </div>
  )
}

